## MatchedGeometryEffect

일반적인 애니메이션 효과는 단일 뷰의 변화를 감지하여 그 변화에 애니메이션을 적용한다. `matchedGeometryEffect`를 이용하여 두 뷰 사이의 변화에 애니메이션 효과를 적용할 수 있다. `matchedGeometryEffect`를 적용하기 위해선 같은 뷰로 인식할 고유한 `id`값과 이 정보를 기억할 `@Namespace`라는 프로퍼티 래퍼가 필요하다.
```swift
struct MatchedGeometryEffectStudy: View {

    @State private var isClicked: Bool = false
    @Namespace private var namespace

    var body: some View {
        VStack {
            if !isClicked {
                RoundedRectangle(cornerRadius: 12)
                	// 애니메이션을 적용할 뷰 지정
                    .matchedGeometryEffect(id: "rectangle", in: namespace)
                    .frame(width: 100, height: 100)
            }
            Spacer()
            if isClicked {
                RoundedRectangle(cornerRadius: 12)
					// 애니메이션을 적용할 뷰 지정
                    .matchedGeometryEffect(id: "rectangle", in: namespace)
                    .frame(width: 200, height: 200)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(.red)
        .onTapGesture {
            withAnimation(.easeInOut) {
                isClicked.toggle()
            }
        }
    }
}
```
