## Publisher, Subscriber

`Publisher`는 데이터 스트림을 생성하는 타입으로, 특정 데이터 소스에서 새로운 값이나 이벤트를 발생시킬 수 있다. `Subscriber`는 `Publisher`에서 발생한 데이터 스트림을 수신하는 타입입니다.
```swift
class SubscriberViewModel: ObservableObject {

    @Published var count: Int = 0
    // AnyCancellable 타입의 인스턴스 저장
    var timer: AnyCancellable?

    init() {
        setUpTimer()
    }

    func setUpTimer() {
    	// 시간 간격으로 이벤트를 생성하는 Publisher
        timer = Timer
            .publish(every: 1, on: .main, in: .common)
            .autoconnect()
            // 발생한 이벤트를 수신하여 처리하는 Subscriber
            .sink { [weak self] _ in
                self?.count += 1
                if let count = self?.count, count >= 10 {
                	// 구독 취소 및 이벤트 생성 중단
                    self?.timer?.cancel()
                }
            }
    }
}
```
`Cancellable`은 취소 가능한 작업을 나타내는 프로토콜 객체이며, `cancel` 메서드를 이용해 `Publisher`가 값을 발생시키는 것을 취소하고 리소스에 대해 해제할 수 있다. `AnyCancellable`은 하나 이상의 `Cancellable` 인스턴스를 저장하는 클래스이며, 필요에 따라 모든 인스턴스를 취소할 수 있다. `store` 메서드를 이용해서 취소 가능한 인스턴스를 `Set`에 저장할 수 있다.(`RxSwift`의 `disposeBag`과 비슷한 개념)
```swift
class SubscriberViewModel: ObservableObject {

    @Published var count: Int = 0
    // AnyCancellable 타입의 인스턴스들을 저장
    var cancellables = Set<AnyCancellable>()

    init() {
        setUpTimer()
    }

    func setUpTimer() {
        Timer
            .publish(every: 1, on: .main, in: .common)
            .autoconnect()
            .sink { [weak self] _ in
            	// guard let을 통한 옵셔널 바인딩
                guard let self = self else { return }
                self.count += 1
                if self.count >= 10 {
					// 구독 취소 및 이벤트 생성 중단
                    for item in self.cancellables {
                        item.cancel()
                    }
                }
            }
            // sink 연산자가 반환하는 AnyCancellable 인스턴스를 cancellables 변수에 저장
            .store(in: &cancellables)
    }
}
```
- `map` 메서드를 이용하여 입력 스트림에서 값을 가져와서 다른 형식이나 다른 값으로 변환할 수 있다.
- `assign` 메서드를 이용하여 `Publisher`의 값을 특정 속성에 할당할 수 있다.
- `sink` 메서드에서는 `[weak self]`를 사용하여 메모리 누수를 방지할 수 있다.
- `debounce` 메서드를 이용하여 최신 값 전달을 입력이 없는 주어진 시간동안 지연시킬 수 있다.
```swift
class SubscriberViewModel: ObservableObject {

    var cancellables = Set<AnyCancellable>()

    @Published var textFieldText: String = ""
    @Published var textIsValid: Bool = false

    init() {
        addTextFieldSubscriber()
    }

    func addTextFieldSubscriber() {
        $textFieldText
			// 최신 값 전달 지연
	        .debounce(for: .seconds(0.5), scheduler: DispatchQueue.main)
			// 다른 형식으로 값 변환
            .map { text -> Bool in
                if text.count > 3 {
                    return true
                }
                return false
            }
            // `Publisher`의 값을 특정 속성에 할당
            // .assign(to: \.textIsValid, on: self)
            // [weak self]를 사용하여 메모리 누수를 방지
            .sink(receiveValue: { [weak self] isValid in
                self?.textIsValid = isValid
            })
            .store(in: &cancellables)
    }
}
```
`combineLatest` 메서드를 이용해서 두 개 이상의 `Publisher`를 결합하여, 각 `Publisher`의 최신 값을 기반으로 새로운 값을 생성할 수 있다.
```swift
class SubscriberViewModel: ObservableObject {

    @Published var count: Int = 0
    var cancellables = Set<AnyCancellable>()

    @Published var textFieldText: String = ""
    @Published var textIsValid: Bool = false

    @Published var showButton: Bool = false

    init() {
        setUpTimer()
        addTextFieldSubscriber()
        addButtonSubscriber()
    }

    func setUpTimer() {
        Timer
            .publish(every: 1, on: .main, in: .common)
            .autoconnect()
            .sink { [weak self] _ in
                guard let self = self else { return }
                self.count += 1
            }
            .store(in: &cancellables)
    }

    func addTextFieldSubscriber() {
        $textFieldText
            .debounce(for: .seconds(0.5), scheduler: DispatchQueue.main)
            .map { text -> Bool in
                if text.count > 3 {
                    return true
                }
                return false
            }
        //            .assign(to: \.textIsValid, on: self)
            .sink(receiveValue: { [weak self] isValid in
                self?.textIsValid = isValid
            })
            .store(in: &cancellables)
    }

    func addButtonSubscriber() {
        $textIsValid
        	// 두 개의 Publisher 결합
            .combineLatest($count)
            .sink { [weak self] isValid, count in
                guard let self = self else { return }
                if isValid && count >= 10 {
                    self.showButton = true
                } else {
                    self.showButton = false
                }
            }
            .store(in: &cancellables)
    }
}
```
![](/image/development/573ddea03f853191f771.png)

클로저가 함수 안에서 바로 실행되는지, 함수가 끝난 뒤에 실행되는지는 메모리와 캡처 방식에 영향을 준다. @escaping은 그 생명주기가 함수의 범위를 벗어난다는 사실을 호출부에 알린다.

## Non-Escaping Closure

일반적으로 함수의 파라미터로 전달된 클로저는 함수 내에서만 실행되며, 함수의 범위를 벗어나면 자동으로 소멸한다.
```swift
class EscapingViewModel: ObservableObject {

    @Published var text: String = "Hello"

    func getData() {
        downloadData { data in
            text = data
        }
    }

    func downloadData(completion: (_ data: String) -> Void) {
    	// 클로저 실행 후 함수 종료
        completion("New Data!")
    }
}
```

## Escaping Closure

`@escaping` 속성이 지정된 클로저는 함수의 범위를 벗어나도 계속해서 실행될 수 있다. 주로 클로저가 비동기(asynchronous) 작업을 수행하는 경우, `@escaping` 속성을 사용하여 클로저가 함수의 범위를 벗어날 수 있도록 허용할 수 있다.
```swift
class EscapingViewModel: ObservableObject {

    @Published var text: String = "Hello"

    func getData() {
    	// 비동기 처리를 위한 약한 참조 처리
        downloadData { [weak self] data in
            self?.text = data
        }
    }

    func downloadData(completion: @escaping (_ data: String) -> Void) {
	    // 함수 종료 후 2초 뒤 클로저 실행
        DispatchQueue.main.asyncAfter(deadline: .now() + 2.0) {
            completion("New Data!")
        }
    }
}
```

## Model 생성 및 Typealias 활용

데이터 모델을 생성하여 여러 데이터에 더 쉽게 접근할 수 있다.
```swift
class EscapingViewModel: ObservableObject {

    @Published var text: String = "Hello"

    func getData() {
        downloadData { [weak self] DownloadResult in
        	// 데이터 접근
            self?.text = DownloadResult.data
        }
    }

    func downloadData(completion: @escaping (DownloadResult) -> Void) {
        DispatchQueue.main.asyncAfter(deadline: .now() + 2.0) {
        	let result = DownloadResult(data: "New Data")
            completion(result)
        }
    }
}

// 데이터 모델 생성
struct DownloadResult {
    let data: String
}
```
`typealias`를 활용하여 코드를 더 간결하게 정리할 수 있다.
```swift
class EscapingViewModel: ObservableObject {

    @Published var text: String = "Hello"

    func getData() {
        downloadData { [weak self] DownloadResult in
            self?.text = DownloadResult.data
        }
    }

    // 지정한 타입의 클로저 파라미터
    func downloadData(completion: @escaping DownloadCompletion) {
        DispatchQueue.main.asyncAfter(deadline: .now() + 2.0) {
        	let result = DownloadResult(data: "New Data")
            completion(result)
        }
    }
}

struct DownloadResult {
    let data: String
}

// 임의 타입명 지정
typealias DownloadCompletion = (DownloadResult) -> Void
```

SwiftUI의 View는 값 타입인데 화면 안의 숫자나 선택 상태는 계속 바뀐다. @State는 이 모순처럼 보이는 부분에서 값의 저장 위치와 화면 갱신을 이어 준다.

## Struct내의 @State

`Struct`는 값 타입이여서 `Struct`내의 값을 변경할 수 없지만, `@State`를 통해 값을 변경할 수 있다. 선언된 변수의 값을 관찰하고 값의 변화가 있을 때 해당 뷰를 업데이트 한다. 뷰의 `body`에서만 접근해야되기 때문에 `private`으로 선언하는 것을 권장한다.
```swift
struct StateStudy: View {

    // 값의 변화 추적
    @State private var count: Int = 0

    var body: some View {
        VStack(spacing: 24) {
            Text("Current Count is \(count)")
            Button("Click to Count") {
                count += 1
            }
        }
    }
}
```
![](/image/development/4dd27e32da8c2e255258.gif)

상태를 여러 단계의 자식 뷰로 계속 전달하다 보면 데이터를 사용하지 않는 중간 뷰까지 매개변수를 갖게 된다. @EnvironmentObject는 공유 객체를 환경에 넣고 실제로 필요한 뷰가 직접 꺼내 쓰게 한다.

## 뷰 간 데이터 공유

`ObservableObject`를 채택한 객체 데이터를 `@StateObject`와 `@ObservedObject`를 통해 뷰 간에 공유할 수 있다. 하지만 이 방법은 직접적으로 데이터를 사용하지 않더라도 전달만을 위해 인스턴스를 생성해야하는 상황이 발생한다.
```swift
// 공유할 데이터
class EnvironmentViewModel: ObservableObject {

    @Published var dataArray: [String] = []

    init() {
        getData()
    }

    func getData() {
        self.dataArray.append(contentsOf: ["iPhone", "iPad", "iMac"])
    }
}

// 첫 번째 뷰
struct FirstView: View {

    // 데이터 생성
    @StateObject var viewModel: EnvironmentViewModel = EnvironmentViewModel()

    var body: some View {
        NavigationStack {
            List {
                ForEach(viewModel.dataArray, id: \.self) { item in
                    NavigationLink {
                        SecondView(viewModel: viewModel, selectedItem: item)
                    } label: {
                        Text(item)
                    }
                }
            }
        }
    }
}

// 두 번째 뷰
struct SecondView: View {

    // 불필요한 데이터 전달
    @ObservedObject var viewModel: EnvironmentViewModel
    let selectedItem: String

    var body: some View {
        NavigationLink {
            ThirdView(viewModel: viewModel)
        } label: {
            Text(selectedItem)
        }
    }
}

// 세 번째 뷰
struct ThirdView: View {

    // 데이터 공유
    @ObservedObject var viewModel: EnvironmentViewModel

    var body: some View {
        ForEach(viewModel.dataArray, id: \.self) { item in
            Text(item)
        }
    }
}
```
![](/image/development/324efad6719cf94149ad.png)

## @EnvironmentObject

`@StateObject`로 생성한 객체 데이터를 `.environmentObject()`를 통해 하위 뷰 전역에 공유할 수 있다. 공유 받은 하위 뷰에서는 데이터가 필요한 특정 뷰까지의 불필요한 전달없이 `@EnvironmentObject`를 통해 바로 사용할 수 있다.
```swift
struct FirstView: View {

    // 데이터 생성
    @StateObject var viewModel: EnvironmentViewModel = EnvironmentViewModel()

    var body: some View {
        NavigationStack {
            List {
                ForEach(viewModel.dataArray, id: \.self) { item in
                    NavigationLink {
                        SecondView(selectedItem: item)
                    } label: {
                        Text(item)
                    }
                }
            }
        }
        // 하위 뷰 전역에 데이터 공유
        .environmentObject(viewModel)
    }
}

struct SecondView: View {

    // 불필요한 전달 없음
    let selectedItem: String

    var body: some View {
        NavigationLink {
            ThirdView()
        } label: {
            Text(selectedItem)
        }
    }
}

struct ThirdView: View {

    // 데이터 공유
    @EnvironmentObject var viewModel: EnvironmentViewModel

    var body: some View {
        ForEach(viewModel.dataArray, id: \.self) { item in
            Text(item)
        }
    }
}
```
![](/image/development/40798b459b009ecbdb4c.png)

뷰가 복잡해질수록 화면, 데이터, 로직을 한 구조체에 두는 일이 버거워진다. 객체의 변화를 관찰하는 방법뿐 아니라 그 객체를 누가 만들고 소유하는지도 함께 구분해야 했다.

## 코드 분리의 필요성

코드의 양이 많아지고 복잡해짐에 따라 협업과 유지보수, 확장성 측면에서 코드를 분리하여 관리해야 한다. 코드의 각 목적에 따라 데이터 모델, 인터페이스 뷰, 데이터 기능 등 세 부분으로 나눌 수 있다.
```swift
// 데이터 모델 부분
struct FruitModel: Identifiable {
    let id: String = UUID().uuidString
    let name: String
    let count: Int
}

struct ViewModelStudy: View {

    @State var fruitArray: [FruitModel] = [
        FruitModel(name: "Apple", count: 5)
    ]

    // 인터페이스 뷰 부분
    var body: some View {
        NavigationStack {
            List {
                ForEach(fruitArray) { fruit in
                    HStack {
                        Text("\(fruit.count)")
                            .foregroundColor(.red)
                        Text(fruit.name)
                    }
                }
                .onDelete { indexSet in
                    deleteFruit(index: indexSet)
                }
            }
            .onAppear {
                getFruits()
            }
        }
    }

    // 로직 및 기능 부분
    func getFruits() {
        let fruit1 = FruitModel(name: "Banana", count: 7)
        let fruit2 = FruitModel(name: "Carrot", count: 3)
        fruitArray.append(fruit1)
        fruitArray.append(fruit2)
    }
    func deleteFruit(index: IndexSet) {
        fruitArray.remove(atOffsets: index)
    }
}
```
![](/image/development/e37cd217dc14da991c77.png)

>**MVVM Architecture**
SwiftUI에서는 보통 MVVM 디자인 패턴에 따라 코드를 분리하여 관리한다.

![](/image/development/b0f06463f57f33ed75d8.png)

## 데이터 모델 분리(Model)

앱에 필요한 데이터를 `Array`, `Struct`등으로 분리하여 관리한다.
```swift
struct FruitModel: Identifiable {
    let id: String = UUID().uuidString
    let name: String
    let count: Int
}
```

## 로직 및 기능 분리(ViewModel)

앱에 필요한 로직 및 기능들을 `Class`를 통해 분리하여 관리한다. 이 때 뷰모델은 `ObservableObject` 프로토콜을 채택(Class에서만 가능)하여 데이터 모델을 관찰하고 변경사항을 뷰에 알리는 역할을 한다. 뷰모델 내의 프로퍼티는 `@Published`를 통해 선언한다.

>**@Published**
해당 객체에 변경사항이 있을 때 자동으로 뷰에 알리고, 뷰를 업데이트하는 역할을 한다.

```swift
class FruitViewModel: ObservableObject {

    // 데이터 모델 관찰
    @Published var fruitArray: [FruitModel] = [
        FruitModel(name: "Apple", count: 5)
    ]

    init() {
        getFruits()
    }

    func getFruits() {
        let fruit1 = FruitModel(name: "Banana", count: 7)
        let fruit2 = FruitModel(name: "Carrot", count: 3)
        fruitArray.append(fruit1)
        fruitArray.append(fruit2)
    }
    func deleteFruit(index: IndexSet) {
        fruitArray.remove(atOffsets: index)
    }
}
```

## 인터페이스 뷰 분리(View)

사용자가 직접 보고 인터랙션하는 부분을 `View`를 통해 분리하여 관리한다. 이 때 분리한 뷰모델을 `@ObservedObjcet`를 통해 관찰 가능한 인스턴스로 생성한다.
```swift
struct ViewModelStudy: View {

    // 뷰모델이 관찰 가능한 인스턴스
    @ObservedObject var fruitViewModel: FruitViewModel = FruitViewModel()

    var body: some View {
        NavigationStack {
            List {
                ForEach(fruitViewModel.fruitArray) { fruit in
                    HStack {
                        Text("\(fruit.count)")
                            .foregroundColor(.red)
                        Text(fruit.name)
                    }
                }
                .onDelete(perform: fruitViewModel.deleteFruit)
            }
        }
    }
}
```

## @ObservedObject와 @StateObject

`@ObservedObject`와 `@StateObject` 모두 기본적으로 뷰 내부에서 관찰 가능한 객체의 인스턴스를 저장하기 위해 사용된다.

|차이|@ObservedObject|@StateObject|
|---|---|---|
|데이터 변화|데이터 변화가 있을 때 뷰를 처음부터 다시 그린다.|데이터 변화가 있을 때 변화가 있는 부분의 뷰만 다시 그린다.
|생명주기|뷰가 사라지고 다시 그려짐에 따라, 인스턴스도 사라지고 다시 생성된다.|초기에 인스턴스가 생성되고 뷰와 상관없이 유지된다.|
|사용|보통 다루는 데이터가 달라지는 하위 뷰에서 사용한다.|보통 데이터를 유지해야하고 초기에 생성되는 상위 뷰에서 사용된다.|
```swift
struct ViewModelStudy: View {

    // 초기에 생성되는 상위 뷰이므로 @StateObject 인스턴스
    @StateObject var fruitViewModel: FruitViewModel = FruitViewModel()

    var body: some View {
        NavigationStack {
            List {
                ForEach(fruitViewModel.fruitArray) { fruit in
                    HStack {
                        Text("\(fruit.count)")
                            .foregroundColor(.red)
                        Text(fruit.name)
                    }
                }
                .onDelete(perform: fruitViewModel.deleteFruit)
            }
            .toolbar {
                ToolbarItem(placement: .navigationBarTrailing) {
                    NavigationLink {
                    	// 하위 뷰 이동 및 동일한 뷰모델(데이터) 전달
                        RandomScreen(fruitViewModel: fruitViewModel)
                    } label: {
                        Image(systemName: "arrow.right")
                    }

                }
            }
        }
    }
}

struct RandomScreen: View {

    // 하위 뷰이므로 @ObservedObject 인스턴스
    @ObservedObject var fruitViewModel: FruitViewModel
    @Environment(\.presentationMode) var presentationMode

    var body: some View {
        VStack {
            ForEach(fruitViewModel.fruitArray) { fruit in
                Text(fruit.name)
            }
        }
    }
}
```
![](/image/development/bbe932a856370328ed2e.png)

화면에 표시할 값이 몇 개 되지 않을 때는 배열만으로 충분해 보인다. 하지만 속성이 늘고 데이터 사이의 관계가 생기면 하나의 모델로 묶는 편이 코드의 의도를 훨씬 잘 보여준다.

## Array 형식

`Array` 형식으로 동일한 타입의 데이터를 선형적으로(순서대로) 정리할 수 있다. `index`를 통해 개별 요소에 접근할 수 있다.
```swift
struct CustomModelStudy: View {

    // Array 형식의 데이터 모델
    @State var users: [String] = [
        "Snack", "Koby", "Hannah", "Kayle", "Goggins"
    ]

    var body: some View {
        List {
        	// index를 통해 개별 요소에 접근
            ForEach(users, id: \.self) { name in
                HStack(spacing: 16) {
                    Circle()
                        .frame(width: 32, height: 32)
                    Text(name)
                }
                .padding(.vertical, 4)
            }
        }
    }
}
```
![](/image/development/12eae14111238344a2dd.png)

## Struct 형식

`struct` 형식으로 여러가지 타입의 데이터를 캡슐화하여 정리할 수 있다. 각 인스턴스의 고유한 식별을 위해 `Identifiable` 프로토콜을 준수할 수 있고, 이를 위해 `UUID`를 사용한다.

> **UUID**
Universally Unique IDentifier의 약자로, 128비트의 값을 갖으며 고유한 식별자로 사용된다.
`E621E1F8-C36C-495A-93FC-0C247A3E6E5F`와 같이 보통 32개의 16진수 숫자와 하이픈으로 구성된 형태로 표현된다.

```swift
struct UserModel: Identifiable {
	// UUID를 String 타입으로 생성
    let id: String = UUID().uuidString
    let displayName: String
    let userName: String
    let followerCount: Int
    let isVerified: Bool
}

struct CustomModelStudy: View {

    @State var users: [UserModel] = [
   		// 각 데이터에 따른 인스턴스 생성
        UserModel(displayName: "Snack", userName: "snack123", followerCount: 100, isVerified: false),
        UserModel(displayName: "Koby", userName: "koby123", followerCount: 200, isVerified: true),
        UserModel(displayName: "Hannah", userName: "hannah123", followerCount: 300, isVerified: false)
    ]

    var body: some View {
        List {
            ForEach(users) { user in
            	// 여러가지 타입의 데이터 표현
                HStack(spacing: 16) {
                    Circle()
                        .frame(width: 40, height: 40)
                    VStack(alignment: .leading) {
                        Text(user.displayName)
                        Text("@\(user.userName)")
                            .foregroundColor(.gray)
                            .font(.caption)
                    }
                    if user.isVerified {
                        Image(systemName: "checkmark.seal.fill")
                            .foregroundColor(.blue)
                    }
                    Spacer()
                    VStack {
                        Text("\(user.followerCount)")
                            .font(.headline)
                        Text("Followers")
                            .foregroundColor(.gray)
                            .font(.caption)
                    }
                }
                .padding(.vertical, 4)
            }
        }
    }
}
```
![](/image/development/5a9f8a0cde7b1c61abbb.png)

기기 화면의 크기만 기준으로 레이아웃을 잡으면 분할 화면이나 부모 뷰의 변화에 제대로 반응하지 못한다. GeometryReader는 지금 이 뷰에 실제로 제안된 공간을 기준으로 계산하게 해준다.

## UIScreen

`UIScreen`을 활용하여 화면의 너비에 따라 레이아웃이나 위치를 지정할 수 있다. 모든 상황에서 화면의 너비를 기준으로 하기 때문에 `Landscape`모드 등 유동적으로 적용되지 않는다.
```swift
HStack(spacing: 0) {
    Rectangle()
        .fill(.red)
        // 화면 너비의 3/2 크기
        .frame(width: UIScreen.main.bounds.width * 0.666)
    Rectangle()
        .fill(.blue)
}
.ignoresSafeArea()
```
![](/image/development/4275b1c115d12eb297ad.png)

## GeometryReader

상위 뷰의 주어진 공간 내에서 하위 뷰의 위치와 크기를 유동적으로 결정할 수 있다. 클로저 내에서 `GeometryProxy`를 통해 상위 뷰 정보에 접근할 수 있다. `GeometryReader`는 리소스를 많이 차지하기 때문에 남용하지 말고 꼭 필요한 상황에서만 사용해야한다.
```swift
GeometryReader { geometry in
    HStack(spacing: 0) {
        Rectangle()
            .fill(.red)
            // 상위 뷰 너비의 3/2 크기
            .frame(width: geometry.size.width * 0.666)
        Rectangle()
            .fill(.blue)
    }
    .ignoresSafeArea()
}
```
![](/image/development/8092bf678b8fcf4d475f.png)

## GeometryReader Frame

`frmae(in:)`을 통해 특정 좌표계를 기준으로 한 프레임 정보를 가저올 수 있다.
```swift
enum CoordinateSpace {
  case global // 화면 전체 영역 기준
  case local // GeometryReader 기준
  case named(AnyHashable) // 명시적으로 이름을 할당한 공간 기준
}    
```
![](/image/development/592a4df3015032cc8b3d.png)

`GeometryReader`를 활용하여 다양한 특수효과를 표현할 수 있다.
```swift
struct GeometryReaderStudy: View {
    var body: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack {
                ForEach(0..<20) { index in
                    GeometryReader { geometry in
                        RoundedRectangle(cornerRadius: 20)
                            .rotation3DEffect(
                            	// 카드의 현재 위치에 따라 각도를 다르게 조절
                                Angle(degrees: getPercentage(geo: geometry)) * 20,
                                axis: (x: 0.0, y: 1.0, z: 0.0))
                    }
                    .frame(width: 300, height: 250)
                    .padding()
                }
            }
        }
    }
    func getPercentage(geo: GeometryProxy) -> Double {
    	// 화면의 중앙 위치
        let maxDistance = UIScreen.main.bounds.width / 2
        // 화면 전체 영역 기준 카드의 현재 중앙 좌표
        let currentX = geo.frame(in: .global).midX
        // 두 위치에 대한 비율 계산
        return Double(1 - (currentX / maxDistance))
    }
}
```
![](/image/development/0b80b14215485a2d3d44.gif)

긴 목록에서 특정 항목으로 바로 이동하려면 스크롤 거리보다 대상의 식별자가 필요하다. ScrollViewReader가 내부의 뷰를 찾고 위치를 옮기는 방법을 안과 밖의 호출로 나누어 봤다.

## ScrollView 내부에서 제어

일반적으로 `ScrollView` 내부의 포함되는 뷰의 식별자를 사용하여 특정 뷰로 스크롤할 수 있다. `id`값을 지정하여 해당 위치의 뷰로 스크롤할 수 있고, `anchor`를 통해 스크롤된 뷰의 위치를 지정할 수 있다.
```swift
ScrollView {
    ScrollViewReader { proxy in
        Button("Click here to go to #49") {
            withAnimation(.spring()) {
            	// 특정 id값의 위치로 스크롤
                proxy.scrollTo(30, anchor: .center)
            }
        }
        ForEach(0..<50) { index in
            Text("This is item #\(index)")
                .font(.headline)
                .frame(height: 200)
                .frame(maxWidth: .infinity)
                .background(Color.white)
                .cornerRadius(16)
                .shadow(radius: 10)
                .padding()
                .id(index) // id값 생성
        }
    }
}
```
![](/image/development/71822ec2e2a9a6907594.png)

## ScrollView 외부에서 제어

`TextField`와 `onChange`를 활용하여 `ScrollView` 외부에서 스크롤 위치를 제어할 수 있다.
```swift
struct ScrollViewReaderStudy: View {

    @State var scrollToIndex: Int = 0
    @State var textFieldText: String = ""

    var body: some View {
        VStack {
        	// String 타입으로 스크롤할 ScrollView의 특정 위치를 입력
            TextField("scroll number", text: $textFieldText)
                .frame(height: 56)
                .border(.gray)
                .padding(.horizontal)
                .keyboardType(.numberPad)
            Button("Scroll Now") {
            	// Int 타입으로 입력받은 위치를 변환
                if let index = Int(textFieldText) {
                    scrollToIndex = index
                }
            }
            ScrollView {
                ScrollViewReader { proxy in
                    ForEach(0..<50) { index in
                        Text("This is item #\(index)")
                            .font(.headline)
                            .frame(height: 200)
                            .frame(maxWidth: .infinity)
                            .background(Color.white)
                            .cornerRadius(16)
                            .shadow(radius: 10)
                            .padding()
                            .id(index)
                    }
                    // 입력받은 Int 타입의 위치 값이 변할 때 해당 위치로 스크롤
                    .onChange(of: scrollToIndex) { newValue in
                        withAnimation {
                            proxy.scrollTo(newValue, anchor: .center)
                        }
                    }
                }
            }
        }
    }
}
```
![](/image/development/1b13f43c7028ec6cc226.png)

화면 이동을 단순한 링크 모음으로 보면 깊어진 경로를 코드에서 다루기 어렵다. NavigationStack은 이동 기록을 값으로 표현해 현재 경로를 읽고 바꿀 수 있게 한다.

## NavigationLink

다른 화면으로 이동하며 네비게이션 스택에 새로운 뷰를 푸시(push)하고 이전 뷰로 돌아갈 수 있는 탐색 기능을 제공한다.
```swift
NavigationStack {
    List {
    	// 각각의 새로운 뷰로 이동
        NavigationLink("Red", destination: Text("Red"))
        NavigationLink("Green", destination: Text("Green"))
        NavigationLink("Blue", destination: Text("Blue"))
    }
    .navigationTitle("Colors") // 네비게이션 제목
}
```

## NavigationDestination

`DestinationView`를 `NaviationLink`에서 제시된 데이터 타입과 연결해준다. `NavigationView`와 달리 `DestinationView`가 미리 로드되지 않는다.
```swift
NavigationStack {
    List {
        NavigationLink("Red", value: Color.red)
        NavigationLink("Green", value: Color.green)
        NavigationLink("Blue", value: Color.blue)
    }
    // value 값에 따라 모든 네비게이션의 다음 뷰 지정
    .navigationDestination(for: Color.self, destination: { color in
        ColorDetail(color: color)
    })
    .navigationTitle("Colors")
}
```
`NavigationLink`에서 제시된 데이터 타입과 `NavigationDestination`의 데이터 타입이 같지 않으면 화면이 이동하지 않는다.
```swift
struct ColorDetail: View {

    var color: Color

    var body: some View {
            Text("\(self.color.description)")
    }
}
```
데이터 타입이 여러 종류일 경우, `NavigationDestination` 여러 개 사용하면 된다.
```swift
NavigationStack {
    List {
        NavigationLink("Red", value: Color.red)
        NavigationLink("Green", value: Color.green)
        NavigationLink("Blue", value: "blue")
    }
    .navigationDestination(for: Color.self, destination: { color in
        ColorDetailForColor(color: color) // Color 타입
    })
    .navigationDestination(for: String.self, destination: { color in
        ColorDetailForString(color: color) // String 타입
    })
    .navigationTitle("Colors")
}
```

## Navigation State

`NavigationStack`은 상태를 관리하여 스택 내의 뷰들을 추적 관리할 수 있다. `NavigationPath` 타입의 `State`변수를 만들어 화면 간 네비게이션 경로를 저장할 수 있다. 스택의 마지막 요소를 제거하여 이전 화면으로 돌아가거나, 스택을 초기화해 최초 뷰로 이동할 수 있다.
```swift
struct NavigationStackStudy: View {

    // 네비게이션 경로 추적
    @State var stack: NavigationPath = NavigationPath()

    var body: some View {
        NavigationStack(path: $stack) {
            List {
                NavigationLink("Red", value: Color.red)
                NavigationLink("Green", value: Color.green)
                NavigationLink("Blue", value: Color.blue)
            }
            .navigationDestination(for: Color.self, destination: { color in
                ColorDetail(stack: $stack, color: color)
				NavigationLink("Yellow", value: Color.yellow) // 무한히 쌓이는 스택

            })
            .navigationTitle("Colors")
        }
    }
}

struct ColorDetail: View {

    @Binding var stack: NavigationPath
    var color: Color

    var body: some View {
        Text("\(self.color.description)")
        Button("Back") {
            stack.removeLast() // 이전 화면으로 돌아가기
        }
        Button("First") {
        	stack = .init() // 최초 화면으로 돌아가기
        }
    }
}
```
네비게이션 경로 값을 직접 입력하여 원하는 경로의 뷰로 바로 이동(딥링크) 및 복귀 할 수 있다.
```swift
struct NavigationStackStudy: View {

    // 네비게이션 경로 추적
    @State var stack: [Color] = []

    var body: some View {
        NavigationStack(path: $stack) {
            List {
                NavigationLink("Red", value: Color.red)
                NavigationLink("Green", value: Color.green)
                NavigationLink("Blue", value: Color.blue)
                Button("Go to Yellow") {
                	// 경로 직접 입력
                    stack = [.red, .green, .blue, .yellow]
                }
            }
            .navigationDestination(for: Color.self, destination: { color in
                ColorDetail(color: color)
            })
            .navigationTitle("Colors")
        }
    }
}

struct ColorDetail: View {

    var color: Color

    var body: some View {
        Text("\(self.color.description)")
    }
}
```

앱을 다시 열어도 다크 모드나 온보딩 완료 여부 같은 작은 설정은 남아 있어야 한다. @AppStorage는 UserDefaults의 키-값 저장 방식과 SwiftUI의 화면 갱신을 짧은 선언으로 연결한다.

## UserDefaults

앱의 설정 데이터, 사용자 기본값 같은 간단한 상태 정보 등을 저장하고 검색하는 데 사용되는 인터페이스이다. `key-value` 형식으로 데이터를 저장하며, 각 데이터 항목에는 유일한 키와 해당 데이터의 값이 포함된다.
```swift
// 값 저장
UserDefaults.standard.set(true, forKey: "isOnboardingShown")
UserDefaults.standard.set(10, forKey: "tapCount")
UserDefaults.standard.set("Snack", forKey: "userName")

// 값 검색
let isOnboardingShown = UserDefaults.standard.bool(forKey: "isOnboardingShown") // true
let tapCount = UserDefaults.standard.integer(forKey: "tapCount") // 10
let userName = UserDefaults.standard.string(forKey: "userName") // "Snack"
```
저장된 데이터는 앱이 종료되어도 유지된다.
```swift
struct AppStorageStudy: View {

    @State var currentUserName: String?

    var body: some View {
        VStack(spacing: 20) {
            Text(currentUserName ?? "DefaultName")
            Button("Save") {
            	// 저장할 데이터
                let name: String = "Snack"
                currentUserName = name
                // 키 값으로 데이터 저장
                UserDefaults.standard.set(name, forKey: "userName")
            }
        }
        .onAppear {
        	// 키 값에 따른 데이터 검색
            currentUserName = UserDefaults.standard.string(forKey: "userName")
        }
    }
}
```

## @AppStorage

`@AppStorage`를 사용하면 영구적으로 유지할 데이터가 `UserDefaults`에 자동으로 저장되고 검색할 수 있다. `@AppStorage` 키워드와 함께 해당 데이터를 식별할 키값을 같이 선언한다.
```swift
struct AppStorageStudy: View {
    // 키 값으로 데이터 저장
    @AppStorage("userName") var currentUserName: String?

    var body: some View {
        VStack(spacing: 20) {
            Text(currentUserName ?? "DefaultName")
            Button("Save") {
                let name: String = "Snack"
                currentUserName = name
            }
        }
    }
}
```
`@AppStorage`로 선언된 프로퍼티는 값을 읽거나 변경할 때마다 `UserDefaults`가 자동으로 업데이트되고 해당 값을 사용할 수 있다.

버튼처럼 보이지 않는 화면 요소에도 탭 동작이 필요할 때가 있다. onTapGesture가 기본 Button과 다른 점, 여러 번의 탭과 탭 위치를 구분하는 방법을 살펴봤다.

## onTapGesture

사용자가 특정 뷰를 탭하면 실행할 코드를 지정하여, 제스처가 인식되면 지정된 코드 블럭을 실행한다. 일반 버튼과 다르게 뷰가 탭 됐을 때 하이라이트 되지 않는다.
```swift
struct TapGestureStudy: View {

    @State var isSelected: Bool = false

    var body: some View {
        VStack(spacing: 40){
            RoundedRectangle(cornerRadius: 32)
                .foregroundColor(isSelected ? .green : .yellow)
                .frame(height: 200)
            // 일반 버튼
            Button {
                isSelected.toggle()
            } label: {
                Text("Button")
                    .foregroundColor(.white)
                    .frame(height: 50)
                    .frame(maxWidth: .infinity)
                    .background(Color.blue)
                    .cornerRadius(25)
            }
            // 버튼 형태의 Text뷰
            Text("Tap Gesture")
                .foregroundColor(.white)
                .frame(height: 50)
                .frame(maxWidth: .infinity)
                .background(Color.blue)
                .cornerRadius(25)
                // 탭 제스처 인식 시 해당 코드 실행
                .onTapGesture {
                    isSelected.toggle()
                }
        }
        .padding()
    }
}
```

## Count

`count` 파라미터를 통해 인식될 탭 횟수를 지정할 수 있다. 사용자는 지정된 횟수만큼 연속으로 탭해야 코드가 실행된다.
```swift
struct TapGestureStudy: View {

    @State var isSelected: Bool = false

    var body: some View {
        VStack(spacing: 40){
            RoundedRectangle(cornerRadius: 32)
                .foregroundColor(isSelected ? .green : .yellow)
                .frame(height: 200)
            Text("Tap Gesture")
                .foregroundColor(.white)
                .frame(height: 50)
                .frame(maxWidth: .infinity)
                .background(Color.blue)
                .cornerRadius(25)
                // 연속을 3번 탭해야 코드 실행
                .onTapGesture(count: 3) {
                    isSelected.toggle()
                }
        }
        .padding()
    }
}
```

옵셔널을 꺼내는 두 문법은 결과만 보면 비슷하지만 이후 코드가 흐르는 방향은 정반대다. 조건 안에서 짧게 사용할지, 실패를 먼저 끝내고 정상 흐름을 이어갈지에 따라 선택이 달라진다.

## if let

조건문 안의 옵셔널 값이 `nil`인지 체크하고, 각 경우에 대한 처리를 안전하게 수행한다. 보통 각 조건에 따른 처리를 위해 사용되지만, `else`문을 생략하고 사용할 수 있다. 옵셔널 바인딩 된 상수 `if`문 안에서만 사용할 수 있다.
```swift
struct UnwrapStudy: View {

    @State var currentUserID: String? = "Snack"
    @State var displayText: String? = nil
    @State var isLoading: Bool = false

    var body: some View {
        VStack {
        	// displayText가 nil이 아닌 경우
            if let text = displayText {
                Text(text)
                    .font(.title)
            }
            if isLoading {
                ProgressView()
            }
        }
        .onAppear {
            loadData()
        }
    }

    func loadData() {
		// currentUserID가 nil이 아닌 경우
        if let userID = currentUserID {
            isLoading = true
            DispatchQueue.main.asyncAfter(deadline: .now() + 3) {
                displayText = "The username is \(userID)."
                isLoading = false
            }
        // currentUserID가 nil인 경우
        } else {
            displayText = "There is no user data."
        }
    }
}
```

## guard let

- 블록 내부에서만 사용되며, 옵셔널 값을 체크하여 `nil`인 경우에 대한 처리를 `guard` 절 안에서 바로 수행한다.
- `return`, `break`, `continue`, `throw` 등의 제어문 전환 명령어를 필수로 입력한다.
- 옵셔널 바인딩 된 상수를 `else`문을 제외한 블록 내에서 사용할 수 있다.
- 예외사항 처리를 먼저 수행하여 코드의 안정성과 가독성이 향상된다.
```swift
struct UnwrapStudy: View {

    @State var currentUserID: String? = "Snack"
    @State var displayText: String? = nil
    @State var isLoading: Bool = false

    var body: some View {
        VStack {
	        // displayText가 nil이 아닌 경우
            if let text = displayText {
                Text(text)
                    .font(.title)
            }
            if isLoading {
                ProgressView()
            }
        }
        .onAppear {
            loadData()
        }
    }

    func loadData() {
        guard let userID = currentUserID else {
        	// currentUserID가 nil인 경우
            displayText = "There is no user data."
            return // 함수 종료
        }
        // currentUserID가 nil이 아닌 경우
        isLoading = true
        DispatchQueue.main.asyncAfter(deadline: .now() + 3) {
            displayText = "The username is \(userID)."
            isLoading = false
        }
    }
}
```

뷰의 위치나 색이 바뀌는 애니메이션과 뷰 자체가 계층에 들어오고 나가는 전환은 다르게 동작한다. transition을 적용했는데 움직이지 않았던 경우까지 함께 살펴봤다.

## Animation Transition 효과

먼저 뷰에 애니메이션을 적용시킨 후, 조건문을 활용하여 뷰에 전환 효과를 적용시킬 수 있다.

```swift
struct TransitionStudy: View {

    @State var isAnimation: Bool = false

    var body: some View {
        VStack {
            Button("Button") {
            	// animation 효과 적용
                withAnimation {
                    isAnimation.toggle()
                }
            }
            Spacer()
            if isAnimation {
                RoundedRectangle(cornerRadius: 24)
                    .frame(height: UIScreen.main.bounds.height / 2)
                    // transition 효과 적용
                    .transition(.slide)
            }
        }
        .edgesIgnoringSafeArea(.bottom)
    }
}
```
![](/image/development/c0dfc6279e1b922ce732.gif)

## Transition 종류

AnyTransition의 다양한 전환 효과를 적용시킬 수 있다.
```swift
.transition(.opacity)
.transition(.scale)
.transition(.slide)
.transition(.move(edge: .leading))
.transition(.push(from: .leading))
.transition(.offset(y: 100))
```
`asymmetric`을 활용하여 등장과 퇴장할 때의 전환 효과를 다르게 적용시킬 수 있다.
```swift
.transition(.asymmetric(
	insertion: .move(edge: .leading), // 등장 효과
	removal: .opacity // 퇴장 효과
))
```
`combined`을 활용하여 서로 다른 전환 효과를 동시에 적용시킬 수 있다.
```swift
.transition(.opacity.combined(with: .scale))
```

## Removal Transition 오류

Removal Transition 시 `zIndex`가 0으로 변경되어, 애니메이션 적용이 안되는 것 처럼 보이는 경우가 있다. 이 때, `zIndex`를 명시적으로 설정하여 해결할 수 있다.
```swift
struct TransitionStudy: View {

    @State var isAnimating = false

    var body: some View {
        ZStack {
            Color.green
            	.zIndex(-1) // 배경의 zIndex를 설정할 경우
                .ignoresSafeArea()
                .onTapGesture {
                    withAnimation(.easeInOut) {
                        isAnimating.toggle()
                    }
                }
            if isAnimating {
                RoundedRectangle(cornerRadius: 24)
                    .zIndex(1) // 전경의 zIndex를 설정할 경우
                    .transition(.move(edge: .bottom))
                    .onTapGesture {
                        withAnimation(.easeInOut) {
                            isAnimating.toggle()
                        }
                    }
            }
        }
    }
}
```

화면이 보일 때 데이터를 불러오고 사라질 때 작업을 정리하는 코드는 어디에 두어야 할까. onAppear와 onDisappear는 간단하지만 뷰가 다시 계산되는 흐름 속에서 호출 시점을 주의해서 봐야 한다.

## onAppear

뷰가 화면 상에 나타날 때 입력된 코드를 실행한다.
```swift
struct OnAppearStudy: View {

    @State var myText: String = "Star Text"

    var body: some View {
        Text(myText)
            .font(.largeTitle)
            // 뷰가 나타난 직후 해당 코드 실행
            .onAppear(perform: {
            	// 3초 후 해당 코드 실행
                DispatchQueue.main.asyncAfter(deadline: .now() + 3) {
                    myText = "Next Text"
                }
            })
    }
}
```
LazyVStack으로 화면에 나타난 후에 데이터를 로드하면, 화면에 나타날 때 `onAppear`내의 코드가 실행된다.
```swift
struct OnAppearStudy: View {

    @State var count: Int = 0

    var body: some View {
        NavigationView {
            ScrollView {
            	// 화면에 나타날 때 데이터 로드
                LazyVStack {
                    ForEach(0..<20) { _ in
                        RoundedRectangle(cornerRadius: 20)
                            .frame(height: 200)
                            .padding()
                            // 화면에 나타날 때 해당 코드 실행
                            .onAppear {
                                count += 1
                            }
                    }
                }
            }
            .navigationTitle("On Appear \(count)")
        }
    }
}
```
![](/image/development/07648427ed474dc7d67a.png)

## onDisappear

뷰가 화면 상에서 사라질 때 입력된 코드를 실행한다.
```swift
struct OnAppearStudy: View {

    @State var myText: String = "Star Text"

    var body: some View {
        Text(myText)
            .font(.largeTitle)
            // 뷰가 사라진 직후 해당 코드 실행
            .onDisappear(perform: {
            	myText = "End Text"
            })
    }
}
```

여러 행동 중 하나를 고르게 할 때 화면 한가운데의 Alert보다 아래에서 올라오는 선택지가 자연스러운 경우가 있다. iOS 버전에 따라 ActionSheet와 confirmationDialog를 어떻게 나눠 써야 하는지 살펴봤다.

## ActionSheet(iOS 13.0-14.0)

iOS 14를 끝으로 더이상 사용되지 않지만, iOS 13과 14를 지원하기 위해서는 `ActionSheet`로 구현해야한다. 일반적으로 두 개 이상의 선택지가 있고, 사용자가 선택을 하면 ActionSheet는 사라지고 해당 액션을 실행한다.

```swift
struct ActionSheetStudy: View {

    @State var showActionSheet: Bool = false // 상태 변수

    var body: some View {
        Button("Click Here!") {
            showActionSheet.toggle() // showActionSheet를 true로 설정
        }
        // ActionSheet 뷰
        .actionSheet(isPresented: $showActionSheet) {
            ActionSheet(
                title: Text("Title"),
                message: Text("This is message."),
                buttons: [
                    .default(Text("Button 1")), // 첫 번째 버튼
                    .destructive(Text("Button 2")), // 두 번째 버트
                    .cancel() // 취소 버튼
                ])
        }
    }
}
```
`default`는 기본적인 버튼 스타일로, 주로 `확인`과 같은 긍정적인 동작을 수행하는 버튼에 사용된다. `cancel`은 주로 `취소`와 같은 부정적인 동작을 수행하는 버튼에 사용된다. `destructive`는 `삭제` 주의를 불러일으키는 동작을 수행하는 버튼에 사용된다.
![](/image/development/9eb1b05f95d95a903c6e.png)

## Customizing

ActionSheet를 함수로 추출하고 enum을 활용하여 각 케이스에 맞는 ActionSheet를 표시할 수 있다.
```swift
struct ActionSheetStudy: View {

    @State var showActionSheet: Bool = false
    @State var actionSheetType: MyActionSheetType = .isOtherPost

    // ActionSheet 케이스 정의
    enum MyActionSheetType {
        case isMyPost
        case isOtherPost
    }

    var body: some View {
        VStack(spacing: 40) {
            Button("My Post") {
                actionSheetType = .isMyPost // MyPost 케이스
                showActionSheet.toggle()
            }
            .actionSheet(isPresented: $showActionSheet, content: getActionSheet)
            Button("Other Post") {
                actionSheetType = .isOtherPost // OtherPost 케이스
                showActionSheet.toggle()
            }
            .actionSheet(isPresented: $showActionSheet, content: getActionSheet)
        }
    }

    func getActionSheet() -> ActionSheet {

        let shareButton: ActionSheet.Button = .default(Text("Share"))
        let reportButton: ActionSheet.Button = .destructive(Text("Report"))
        let deleteButton: ActionSheet.Button = .destructive(Text("Delete"))

        // 케이스에 따른 ActionSheet
        switch actionSheetType {
        case .isMyPost:
            return ActionSheet(
                title: Text("My Post"),
                buttons: [
                    shareButton,
                    deleteButton,
                    .cancel()
                ])
        case .isOtherPost:
            return ActionSheet(
                title: Text("Other Post"),
                buttons: [
                    shareButton,
                    reportButton,
                    .cancel()
                ])
        }
    }
}
```

## ConfirmationDialog(iOS 15.0+)

iOS 15 이상부터 `confirmationDialog`로 `actionSheet`가 대체된다.
```swift
struct ActionSheetStudy: View {

    @State var showActionSheet: Bool = false // 상태 변수

    var body: some View {
        Button("Click Here!") {
            showActionSheet.toggle() // showActionSheet를 true로 설정
        }
        // ActionSheet 뷰
        .confirmationDialog("Title", isPresented: $showActionSheet, titleVisibility: .visible) {
            Button("Button 1") {} // 첫 번째 버튼
            Button("Button 2", role: .destructive) {} // 두 번째 버튼
            Button("Cancel", role: .cancel) {} // 취소 버튼
        } message: {
            Text("This is message.")
        }
    }
}
```

Alert는 짧은 메시지 하나를 보여주는 뷰지만 표시 상태와 버튼의 역할이 섞이면 금방 복잡해진다. 확인만 받는 경우와 두 행동 중 하나를 고르는 경우를 나누어 구성했다.

## 확인 Alert

Alert 메시지를 표시하고, 사용자는 메시지를 확인할 수 있다.
