struct AlertStudy: View {

    @State var showAlert: Bool = false // 상태 변수

    var body: some View {
        Button("Click Here!") {
            showAlert.toggle() // showAlert를 true로 설정
        }
        // Alert 뷰
        .alert(isPresented: $showAlert) {
            Alert(title: Text("There was an error!"))
        }
    }
}
```
