## 선택 Alert

- Alert 메시지를 표시하고, 사용자는 다음 액션에 대해 선택할 수 있다.
- `primaryButton`는 주 버튼으로 설정되며, `secondaryButton`는 보조 버튼으로 설정된다.
- `default`는 기본적인 버튼 스타일로, 주로 `확인`과 같은 긍정적인 동작을 수행하는 버튼에 사용된다.
- `cancel`은 주로 `취소`와 같은 부정적인 동작을 수행하는 버튼에 사용된다.
- `destructive`는 `삭제` 주의를 불러일으키는 동작을 수행하는 버튼에 사용된다.
```swift
struct AlertStudy: View {

    @State var showAlert: Bool = false
    @State var backgroundColor: Color = .white

    var body: some View {
        ZStack {
            backgroundColor.edgesIgnoringSafeArea(.all)
            Button("Click Here!") {
                showAlert.toggle()
            }
            // Alert 뷰
            .alert(isPresented: $showAlert) {
                Alert(
                    title: Text("Alert Title"),
                    message: Text("This is message."),
                    // 액션 버튼
                    primaryButton: .destructive(Text("Change"), action: {
                        backgroundColor = .yellow
                    }),
                    // 취소 버튼
                    secondaryButton: .cancel()
                )
            }
        }
    }
}
```
![](/image/development/8800f19c2af2dc8a9430.png)

## Customizing

Alert를 함수로 추출하고 버튼 별로 `title`과 `message`를 원하는 내용으로 커스터마이징할 수 있다.
```swift
struct AlertStudy: View {

    @State var showAlert: Bool = false
    @State var alertTitle: String = "" // title 변수
    @State var alertMessage: String = "" // message 변수

    var body: some View {
        VStack(spacing: 40) {
        	// Error 버튼
            Button("Error Button") {
	            // Error Title
                alertTitle = "Error Alert"
                // Error Message
                alertMessage = "This is Error Alert Message."
                showAlert.toggle()
            }
            .alert(isPresented: $showAlert) {
                getAlert()
            }
            // Success 버튼
            Button("Success Button") {
            	// Success Title
                alertTitle = "Success Alert"
                // Success Message
                alertMessage = "This is Success Alert Message."
                showAlert.toggle()
            }
            .alert(isPresented: $showAlert) {
                getAlert()
            }
        }
    }

    // Alert 함수
    func getAlert() -> Alert {
        return Alert(
            title: Text(alertTitle),
            message: Text(alertMessage),
            dismissButton: .default(Text("Ok"))
        )
    }
}
```
enum을 활용하여 각 케이스에 맞는 Alert을 표시할 수 있다.
```swift
struct AlertStudy: View {

    @State var showAlert: Bool = false
    @State var alertType: MyAlert? = nil

    // Alert 케이스 정의
    enum MyAlert {
        case error
        case success
    }

    var body: some View {
        VStack(spacing: 40) {
            Button("Error Button") {
                alertType = .error // error 케이스
                showAlert.toggle()
            }
            .alert(isPresented: $showAlert) {
                getAlert()
            }
            Button("Success Button") {
                alertType = .success // success 케이스
                showAlert.toggle()
            }
            .alert(isPresented: $showAlert) {
                getAlert()
            }
        }
    }

    func getAlert() -> Alert {
    	// 케이스에 따른 Alert
        switch alertType {
        case .error:
            return Alert(
                title: Text("Error Alert"),
                message: Text("This is Error Alert Message."),
                dismissButton: .default(Text("Ok"))
            )
        case .success:
            return Alert(
                title: Text("Success Alert"),
                message: Text("This is Success Alert Message."),
                dismissButton: .default(Text("Ok"))
            )
        default:
            return Alert(title: Text("Error"))
        }
    }
}
```

List는 데이터를 세로로 보여주는 데서 시작하지만 실제 화면에서는 그룹을 나누고 항목을 지우거나 옮기고 새로 추가해야 한다. 작은 장보기 목록을 확장하며 각 기능이 어디에 붙는지 살펴봤다.

## List Contents

List 생성자에 뷰를 전달하면, 뷰 하나의 `row` 하나씩 표현한다.
```swift
List {
	Text("apple") // 첫 번째 row
	Text("banana") // 두 번째 row
	Text("oragne") // 세 번째 row
}
```
`id`로 식별할 수 있는 데이터를 받아 `ForEach`를 활용하여 동적으로 뷰를 생성할 수 있다.
```swift
struct ListStudy: View {

    @State var fruits: [String] = [
        "apple", "banana", "orange"
    ]

    var body: some View {
        List {
        	// fruits 배열을 나타내는 리스트 뷰
            ForEach(fruits, id: \.self) { fruit in
                Text(fruit)
            }
        }
    }
}
```

