## onMove

`onMove`를 활용하여 사용자가 List 내의 데이터 순서를 변경할 수 있다. `onMove`를 활용하기 위해서는 Editing Mode에 진입해야되기 때문에, List를 NavigationView 안에 넣고 `EditButton()`를 추가하는 작업이 선행되어야 한다.
```swift
struct ListStudy: View {

    @State var fruits: [String] = [
        "apple", "banana", "orange"
    ]

    var body: some View {
    	// NaviationView 추가
        NavigationView {
            List {
                Section {
                    ForEach(fruits, id: \.self) { fruit in
                        Text(fruit)
                    }
                    .onDelete(perform: delete)
                    // List 내의 데이터 순서 변경
                    .onMove { indices, newOffset in
                        fruits.move(fromOffsets: indices, toOffset: newOffset)
                    }
                } header: {
                    Text("Fruits")
                }
            }
            .navigationTitle("Grocery List")
            .navigationBarItems(leading: EditButton()) // EditButton 추가
        }
    }

    func delete(indexSet: IndexSet) {
        fruits.remove(atOffsets: indexSet)
    }
}
```
`fruits.move(fromOffsets: indices, toOffset: newOffset)` 코드를 `move`라는 함수로 추출하고, `onMove()` 메서드에 `perform` 파라미터를 사용하여 바로 `move` 함수를 호출할 수 있다. `delete`와 마찬가지로 Trailing Closure 구문을 활용하여 `move`의 파라미터를 생략할 수 있다.
```swift
struct ListStudy: View {

    @State var fruits: [String] = [
        "apple", "banana", "orange"
    ]

    var body: some View {
        NavigationView {
            List {
                Section {
                    ForEach(fruits, id: \.self) { fruit in
                        Text(fruit)
                    }
                    .onDelete(perform: delete)
                    // perform 파라미터를 사용하여 바로 move 함수 호출 및 move 함수의 파라미터 생략
                    .onMove(perform: move)
                } header: {
                    Text("Fruits")
                }
            }
            .navigationTitle("Grocery List")
            .navigationBarItems(leading: EditButton())
        }
    }

    func move(indices: IndexSet, newOffset: Int) {
        fruits.move(fromOffsets: indices, toOffset: newOffset)
    }
    func delete(indexSet: IndexSet) {
        fruits.remove(atOffsets: indexSet)
    }
}
```
